  'user.login.infos': 'NEXTPlutusはAIマルチエージェント株分析補助ツールであり、証券投資コンサルティング資格はございません。 プラットフォーム内のすべての分析結果、スコア、参考意見は過去のデータに基づいてAIによって自動的に生成され、学習、研究、技術交流のみに使用され、投資アドバイスや意思決定の基礎を構成するものではありません。 株式投資には市場リスク、流動性リスク、政策リスク等の様々なリスクが伴い、元本を割り込む可能性があります。 ユーザーは自身のリスク許容度に基づいて独立した決定を行う必要があり、本ツールの使用から生じる投資行動および結果はユーザーが負担するものとします。 市場にはリスクがあり、投資は慎重になる必要があります。',
