  'user.login.legal.content': 'NEXTPlutusはAIマルチエージェント株分析補助ツールであり、証券投資コンサルティング資格はございません。 プラットフォーム内のすべての分析結果、評価、参考意見は過去のデータに基づいてAIによって自動的に生成され、学習、研究、技術交流のみに使用され、投資アドバイスや意思決定の基礎を構成するものではありません。 株式投資には市場リスク、流動性リスク、政策リスク等の様々なリスクが伴い、元本を割り込む可能性があります。 ユーザーは自身のリスク許容度に基づいて独立した決定を行う必要があり、本ツールの使用から生じる投資行動および結果はユーザーが負担するものとします。 市場にはリスクがあり、投資は慎重になる必要があります。',
  'user.login.privacy.title': 'ユーザープライバシーポリシー',
  'user.login.privacy.view': 'ユーザーのプライバシー ポリシーを表示する',
  'user.login.privacy.collapse': 'ユーザーのプライバシー規約を閉じる',
  'user.login.privacy.content': '私たちはあなたのプライバシーとデータ保護を大切にしています。 1) 収集範囲：機能の実現に必要な情報（メールアドレス、携帯電話番号、市外局番、Web3ウォレットアドレスなど）と必要なログ、端末情報のみを収集します。 2) 利用目的：アカウントへのログインおよびセキュリティ確認、サービス機能の提供、トラブルシューティングおよびコンプライアンス要件のため。 3) 保管とセキュリティ: データは暗号化されて保管され、不正なアクセス、開示、損失を防ぐために必要な許可とアクセス制御手段が講じられます。 4) 第三者との共有: 法令で義務付けられている場合、またはサービスの実行に必要な場合を除き、お客様の個人情報は第三者と共有されることはありません。サードパーティのサービス (ウォレット、SMS サービスプロバイダーなど) が関与する場合、機能の実装に必要な最小限の範囲でのみ処理されます。 5) Cookie/ローカル ストレージ: ログイン ステータスと必要なセッション維持 (トークン、PHPSESSID など) に使用され、ブラウザーでクリアまたは制限できます。 6) 個人の権利：法令に基づき、照会、訂正、削除、同意の撤回等を行う権利を行使することができます。 7) 変更と通知: これらの条件が更新されると、ページ上で目立つように表示されます。 このサービスを継続して使用することにより、更新された内容を読み、同意したものとみなされます。 本規約またはその更新に同意できない場合は、サービスの使用を中止し、当社までご連絡ください。',
  'user.login.legal.agreeButton': '同意',
  
