  'fastAnalysis.indicatorsProSubtitle': '以下はバックエンド MarketDataCollector._calculate_indicators と一致（主流端末との比較用）：RSI(14) は Wilder 平滑化。MACD(12,26,9) の EMA 初期値は前 N 本の SMA、DIF は 26 本目以降、DEA は DIF の EMA9（完全なシグナルラインには約 34 本以上必要）。MA は SMA。ピボットは前足の H/L/C。スイングは直近 20 本の H/L 極値。ボリンジャーは SMA(20)±2×母集団 σ、合成価格は BB_upper/BB_lower を使用。ATR(14) は Wilder 方式で最新足まで連鎖計算。量比とレンジ位置の定義はドキュメント INDICATOR_DEFINITIONS_CN.md を参照。',
