  "dashboard.indicator.backtest.executionAssumptions.bodyAggressive1m": "アグレッシブ（仮想通貨）：戦略TF {sig}で同一バーシグナルが発生し、{exec}バー内で完了します（約10秒間隔のライブポーリング）。SL/TPはサブバーでより早くトリガーされる可能性があります。",
