  "dashboard.indicator.backtest.executionAssumptions.bodyNextBar": "シグナルがバーの終値で確認された後、約定は次のバーの始値（プラススリッページ）に基づいて行われます。取引のタイムスタンプは、チャート上のマーカーと比較して、多くの場合1バー分ずれています。",
  "dashboard.indicator.backtest.executionAssumptions.bodySameBar": "シグナルがバーの終値で確認された後、約定はそのバーの終値（プラススリッページ）に基づいて行われます。タイムスタンプはチャートマーカーと一致するため、結果は通常、より楽観的なものとなります。",
  "dashboard.indicator.backtest.executionAssumptions.bodyScriptStandard": "スクリプト戦略のバックテスト：on_barは、戦略の時間枠で確定した各バーで実行されます。スクリプトからの注文は、デフォルトでは次のバーが開いたときに約定します（スリッページと手数料が加算されます）。これはインジケーターの厳密/非厳密切り替えではなく、標準的なスクリプト再生パスです。",
  "dashboard.indicator.backtest.executionAssumptions.bodyStrict": "厳格モード：閉じたバーのみシグナルを発し、次の開いたバーで約定します（スリッページを含む）。ライブの厳格モードとマッチします。保守的ですが、より現実的です。",
