  "dashboard.indicator.expiry.permanent": "永続",
  "dashboard.indicator.guide.intro": "このプラットフォームは、Pythonを使用して独自のテクニカル指標や取引シグナルを作成することをサポートしています。システムには、組み込みのpandasおよびnumpyデータ分析ライブラリが含まれています。標準的なDataFrame操作を使用して、Kラインデータを処理し、チャートを描画したり、売買シグナルをマークしたりできます。",
  "dashboard.indicator.guide.section1.data": "入力データ: df",
  "dashboard.indicator.guide.section1.dataColumns": "<code>df</code> には、以下の列が含まれています（すべて浮動小数点型）。",
  "dashboard.indicator.guide.section1.dataColumnsList": "<code>time</code> (タイムスタンプ、秒)、<code>open</code>、<code>high</code>、<code>low</code>、<code>close</code>、<code>volume</code>",
  "dashboard.indicator.guide.section1.dataDesc": "システムは現在のKラインデータを自動的にPandas DataFrameオブジェクトに変換します。変数名は<code>df</code>です。",
  "dashboard.indicator.guide.section1.dataIndex": "重要: df のインデックスはタイムスタンプ (DatetimeIndex) です。インデックスを保持し、インデックスが失われる <code>.values</code> の使用を避けてください。",
  "dashboard.indicator.guide.section1.dataNote": "データインデックスは古いデータから新しいデータへと並べられています（0が最も古いデータ、最後の行が最新のデータです）。",
  "dashboard.indicator.guide.section1.env": "あなたのコードは、ブラウザベースのPython環境（Pyodide）で実行されます。",
  "dashboard.indicator.guide.section1.libs": "プリインストール済みライブラリ",
  "dashboard.indicator.guide.section1.libsDesc": "以下のライブラリはデフォルトでインポートされているため、再度インポートする必要はありません。",
  "dashboard.indicator.guide.section1.libsList": "<code>pandas</code> (pd)、<code>numpy</code> (np)、<code>math</code>、<code>json</code>",
  "dashboard.indicator.guide.section1.title": "1. 実行環境と定義済み変数",
  "dashboard.indicator.guide.section2.desc": "コードの冒頭で変数をパラメータとして定義できます。システムは、<code>variable = value</code> のようなステートメントを調整可能なパラメータとして解析しようとします。",
  "dashboard.indicator.guide.section2.example": "パラメータ例",
  "dashboard.indicator.guide.section2.exampleCode": "<code>span = 20</code> または <code>multiplier = 2.0</code>",
  "dashboard.indicator.guide.section2.title": "2. パラメータ定義",
  "dashboard.indicator.guide.section3.backtestBuySignal": "<code>df['buy_signal']</code> - ブール系列。Trueは買いシグナルを示します。",
  "dashboard.indicator.guide.section3.backtestExample": "Example:",
  "dashboard.indicator.guide.section3.backtestExampleCode": "<code>df['buy_signal'] = condition_buy</code><br/><code>df['sell_signal'] = condition_sell</code>",
  "dashboard.indicator.guide.section3.backtestNote": "注: チャート表示用に <code>output.signals</code> のみを設定した場合でも、バックテストを有効にするには、これら 2 つの列を設定する必要があります。",
  "dashboard.indicator.guide.section3.backtestRequired": "<strong>バックテストに必要:</strong>",
  "dashboard.indicator.guide.section3.backtestSellSignal": "<code>df['sell_signal']</code> - ブール系列。Trueは売りシグナルを示します。",
  "dashboard.indicator.guide.section3.desc": "インジケーターでバックテストをサポートするには、コード内で次の 2 つの列を設定する必要があります。",
  "dashboard.indicator.guide.section3.title": "3. バックテストシグナルの設定（重要！）",
  "dashboard.indicator.guide.section4.calculatedVars": "<code>calculatedVars</code> - 計算変数（オプション、追加情報の表示用）",
  "dashboard.indicator.guide.section4.desc": "コード実行の最後に、チャートに結果の表示方法を指示するために、<code>output</code> という名前の辞書を定義する必要があります。",
  "dashboard.indicator.guide.section4.fields": "<code>output</code> ディクショナリには、次のフィールドが含まれています。",
