  "dashboard.indicator.guide.section6.title": "6. 信号マーカー（信号）",
  "dashboard.indicator.guide.section7.exampleA": "例A：デュアルEMA戦略（バックテスト対応）",
  "dashboard.indicator.guide.section7.exampleACode": "# 1. 指標の計算<br/>df['ema_fast'] = df['close'].ewm(span=5, adjust=False).mean()<br/>df['ema_slow'] = df['close'].ewm(span=13, adjust=False).mean()<br/><br/># 2. クロスオーバーシグナルの計算<br/>cross_up = (df['ema_fast'] > df['ema_slow']) & (df['ema_fast'].shift(1) <= df['ema_slow'].shift(1))<br/>cross_down = (df['ema_fast'] < df['ema_slow']) & (df['ema_fast'].shift(1) >= df['ema_slow'].shift(1))<br/><br/># 3. 【重要】新しいバックテストシグナル列を設定します (bool)<br/>df['open_long'] = cross_up<br/>df['close_long'] = cross_down<br/>df['open_short'] = cross_down<br/>df['close_short'] = cross_up<br/><br/># 4. チャート表示用のシグナルデータを生成<br/>buy_signals = [df['low'].iloc[i] * 0.995 if cross_up.iloc[i] else None for i in range(len(df))]<br/>sell_signals = [df['high'].iloc[i] * 1.005 if cross_down.iloc[i] else None for i in range(len(df))]<br/><br/># 5. 出力の構築<br/>output = {<br/> \"name\": \"Dual EMA Strategy\",<br/> \"plots\": [<br/> {\"name\": \"EMA 5\", \"data\": df['ema_fast'].tolist(), \"color\": \"#FF6B6B\", \"overlay\": True},<br/> {\"name\": \"EMA 13\", \"data\": df['ema_slow'].tolist(), \"color\": \"#4ECDC4\", \"overlay\": True}<br/> ],<br/> \"signals\": [<br/> {\"type\": \"buy\", \"text\": \"BUY\", \"data\": buy_signals, \"color\": \"#00E676\"},<br/> {\"type\": \"sell\", \"text\": \"SELL\", \"data\": sell_signals, \"color\": \"#FF5252\"}<br/> ]<br/>}",
  "dashboard.indicator.guide.section7.exampleB": "例B：ボリンジャーバンド - チャート表示のみ",
  "dashboard.indicator.guide.section7.exampleBCode": "# ボリンジャーバンドの計算 (チャート表示のみ、バックテストなし)<br/>length = 20<br/>mult = 2.0<br/>df['sma'] = df['close'].rolling(length).mean()<br/>df['std'] = df['close'].rolling(length).std()<br/>df['upper'] = df['sma'] + mult * df['std']<br/>df['lower'] = df['sma'] - mult * df['std']<br/><br/>output = {<br/> \"name\": 「ボリンジャーバンド」、「プロット」：[QD_TOKEN_13__ {\"name\": \"Upper\", \"data\": df['upper'].tolist(), \"color\": \"#FF5252\", \"overlay\": True}、QD_TOKEN_14__ {\"name\": \"Middle\", \"data\": df['sma'].tolist(), \"color\": \"#2196F3\", \"overlay\": True}、QD_TOKEN_15__ {\"name\": \"Lower\", \"data\": df['lower'].tolist(), \"color\": \"#00E676\", \"overlay\": True}<br/> ]QD_TOKEN_17__}",
  "dashboard.indicator.guide.section7.exampleC": "例C：RSI戦略（バックテスト対応）",
  "dashboard.indicator.guide.section7.exampleCCode": "# RSI の計算<br/>delta = df['close'].diff()<br/>up = delta.clip(lower=0)<br/>down = -1 * delta.clip(upper=0)<br/>ema_up = up.ewm(com=13, adjust=False).mean()<br/>ema_down = down.ewm(com=13, adjust=False).mean()<br/>rs = ema_up / ema_down<br/>df['rsi'] = 100 - (100 / (1 + rs))<br/><br/># 取引シグナルの生成<br/>buy_condition = df['rsi'] < 30  # Oversold buy<br/>sell_condition = df['rsi'] > 70 # 買われすぎ売り<br/><br/># 【重要】新しいバックテストシグナル列を設定します (bool)<br/>df['open_long'] = buy_condition<br/>df['close_long'] = sell_condition<br/>df['open_short'] = sell_condition<br/>df['close_short'] = buy_condition<br/><br/># チャートシグナルを生成します<br/>buy_signals = [df['low'].iloc[i] * 0.995 if buy_condition.iloc[i] else None for i in range(len(df))]<br/>sell_signals = [df['high'].iloc[i] * 1.005 if sell_condition.iloc[i] else None for i in range(len(df))]<br/><br/>output = {<br/> \"name\": \"RSI Strategy\",<br/> \"plots\": [<br/> {\"name\": \"RSI\", \"data\": df['rsi'].tolist(), \"color\": \"#9C27B0\", \"overlay\": False},<br/> {\"name\": \"Overbought\", \"data\": [70] * len(df), \"color\": \"#FF5252\", \"style\": \"dashed\", \"overlay\": False},<br/> {\"name\": \"Oversold\", \"data\": [30] * len(df), \"color\": \"#00E676\", \"style\": \"dashed\", \"overlay\": False}<br/> ],<br/> \"signals\": [<br/> {\"type\": \"buy\", \"text\": \"BUY\", \"data\": buy_signals, \"color\": \"#00E676\"},<br/> {\"type\": \"sell\", \"text\": \"SELL\", \"data\": sell_signals, \"color\": \"#FF5252\"}<br/> ]<br/>}",
  "dashboard.indicator.guide.section7.title": "7. 完全なコード例",
  "dashboard.indicator.guide.section8.a1": "A: バックテストシステムには、新しいシグナル列 <code>df['open_long']</code>、<code>df['close_long']</code>、<code>df['open_short']</code>、<code>df['close_short']</code> (ブール値) が必要です。チャート表示用に <code>output.signals</code> を設定した場合でも、バックテストを有効にするにはこれらの列を設定する必要があります。",
  "dashboard.indicator.guide.section8.a2": "A: <code>plots</code> および <code>signals</code> 内の <code>data</code> リストは、K ライン データとまったく同じ長さである必要があります。<code>df['xxx'].tolist()</code> を使用すれば、通常は問題ありません。",
  "dashboard.indicator.guide.section8.a3": "A: Pandasの計算（移動平均など）では、最初にNaNが生成されます。システムはグラフ表示のためにNaNを自動的にnullに変換します。手動でクリーンアップする必要はありませんが、特定のロジックが必要な場合は、<code>df.fillna(0)</code>などのメソッドを使用できます。",
  "dashboard.indicator.guide.section8.a4": "A: 元のdfインデックス（タイムスタンプ）を必ず保持してください。<code>.values</code> を使用して新しいシリーズを作成することは避けてください。操作には、<code>df['close']</code> のように列を直接使用してください。",
  "dashboard.indicator.guide.section8.a5": "A: いいえ。ランタイム環境はブラウザのサンドボックスであり、requestsなどのライブラリを使用して外部APIをリクエストしたり、追加のpipパッケージをインストールしたりすることはできません。使用できるのは、pandas、numpy、math、jsonなどの組み込みライブラリに限られます。",
  "dashboard.indicator.guide.section8.a6": "A：チャートにインジケーターが表示されない場合、通常はPythonコードにエラーがあることが原因です。構文エラーや配列インデックスの範囲外エラーがないか確認してください。まずはローカルのPython環境でアルゴリズムのロジックをデバッグしてから、コードをコピーすることをお勧めします。",
  "dashboard.indicator.guide.section8.a7": "A: <code>df['open_long']</code>/<code>df['close_long']</code>/<code>df['open_short']</code>/<code>df['close_short']</code> のデータ型を確認してください。数値ではなく、ブール値 (True/False) である必要があります。正しい型であることを確認するには、<code>condition.fillna(False).astype(bool)</code> を使用してください。",
  "dashboard.indicator.guide.section8.q1": "Q: なぜ私のインジケーターはバックテストできないのですか？",
  "dashboard.indicator.guide.section8.q2": "Q: データ長の不一致？",
