  "dashboard.indicator.guide.section8.q4": "Q: インデックスの不一致が原因で、すべての信号がNaNになっていますか？",
  "dashboard.indicator.guide.section8.q5": "Q: サードパーティ製のネットワークライブラリを使用できますか？",
  "dashboard.indicator.guide.section8.q6": "Q: コードのデバッグ方法を教えてください。",
  "dashboard.indicator.guide.section8.q7": "Q: バックテストでシグナルが0件と表示されますか？",
