  "fastAnalysis.indicatorsProBadge": "PRO",
  "fastAnalysis.indicatorsProSubtitle": "バックエンド `MarketDataCollector._calculate_indicators` (主流スタイル) に準拠: RSI(14) は Wilder 平滑化されています。MACD(12,26,9) は、終値に SMA シード EMA を使用します。DIF は 26 番目のバーから開始されます。DEA = DIF シリーズの EMA9 (完全なシグナル ラインには 34 個以上のバー)。MA は SMA です。ピボットは前のバーの H/L/C を使用します。スイング = 20 バーの高値/安値の極値。ボリンジャー = SMA(20) ± 2×母集団 σ。集計レベルは BB_upper/BB_lower を使用します。ATR(14) は Wilder で、最新のバーに連鎖されています。ボリューム比率とレンジ ポジションについては、docs/INDICATOR_DEFINITIONS_CN.md を参照してください。",
