  "profile.agentTokens.intro": "Cursor、Claude Code、MCPクライアントがあなたのアカウントに対して/api/agent/v1を呼び出すことができるように、エージェントトークンを発行してください。トークン全体は一度だけ表示されますので、安全に保管してください。",
  "profile.agentTokens.liveRiskAck": "上記のリスクを読み、承諾した上で、ライブ取引可能なT-scopeトークンを希望します。",
  "profile.agentTokens.liveRiskAckRequired": "まず、リスク承認ボックスにチェックを入れてください。",
  "profile.agentTokens.liveRiskTitle": "ライブ取引におけるリスク認識",
  "profile.agentTokens.risk.audit": "監査ログは、エージェントの動作に対する人間のレビューに取って代わるものではありません。",
  "profile.agentTokens.risk.leak": "漏洩したトークンは、取り消されるまで、そのスコープ内でのAPIアクセスを許可します。",
  "profile.agentTokens.risk.liveSwitch": "ライブ取引を行うには、トークンで paper_only=false を設定し、サーバーで AGENT_LIVE_TRADING_ENABLED=true を設定する必要があります。",
  "profile.agentTokens.risk.misconfig": "エージェントの設定ミスや即時の注文注入は、意図しない注文の発生や金銭的損失を引き起こす可能性があります。",
  "profile.agentTokens.risk.rateLimit": "自動トラフィックはプラットフォームや為替レートの制限に達する可能性があり、他のテナントに影響を与える可能性があります。",
  "profile.agentTokens.risk.saasT": "SaaSにおけるTスコープの拡大は、プラットフォームの運用およびコンプライアンスに関する責任範囲を拡大する。",
  "profile.agentTokens.risk.systemLoad": "多数の同時実行エージェントは、データベースプール、ジョブワーカー、およびストラテジースレッドへの負荷を増加させます。",
  "profile.agentTokens.saasWarningIntro": "これはマルチテナント型のホストインスタンスです。ご自身のテナント向けにT（取引）スコープのトークンを発行できます。以下のリスクをご確認ください。",
