  "user.login.infos": "QuantDingerは、証券投資コンサルティングの資格を持たないAIマルチエージェント株式分析ツールです。プラットフォーム上のすべての分析結果、スコア、および参考意見は、過去のデータに基づいてAIによって自動的に生成されたものであり、学習、研究、および技術的な情報交換のみを目的としており、投資助言や意思決定の根拠となるものではありません。株式投資には、市場リスク、流動性リスク、政策リスクなどのリスクが伴い、元本損失につながる可能性があります。ユーザーは、自身のリスク許容度に基づいて独立した意思決定を行い、このツールを使用した投資行動とその結果に伴うあらゆる結果について責任を負う必要があります。市場リスク、投資には注意が必要です。",
  "user.login.legal.agree": "私は法的免責事項を読み、同意します。",
