  "user.login.legal.content": "QuantDingerはAIマルチエージェント株式分析ツールであり、投資アドバイスを提供するものではありません。すべての分析結果、スコア、および参照情報は、過去のデータに基づいてAIによって生成されたものであり、学習、研究、および技術的な情報交換のみを目的としています。これらは投資アドバイスや意思決定の根拠となるものではありません。株式投資には市場リスク、流動性リスク、および政策リスクが伴い、元本損失につながる可能性があります。ユーザーは、自身のリスク許容度に基づいて独立した意思決定を行い、このツールを使用した投資行動および結果に伴うあらゆる結果について責任を負う必要があります。",
