  "user.login.privacy.content": "お客様のプライバシーとデータ保護を重視しています。(1) 収集範囲: サービス提供に必要な情報 (例: メールアドレス、携帯電話番号、国コード、Web3 ウォレット アドレス) と限定的なログ/デバイス データのみを収集します。(2) 利用目的: アカウントのログインとセキュリティ検証、機能のプロビジョニング、トラブルシューティング、コンプライアンス要件。(3) ストレージとセキュリティ: データは暗号化され、アクセス制御されているため、不正アクセス、開示、または損失を防ぎます。(4) 共有と第三者: 法律で義務付けられている場合、またはサービスを提供する場合を除き、個人データを第三者と共有しません。第三者サービス (例: ウォレット、SMS プロバイダー) が関与する場合、処理は必要最小限の範囲に限定されます。(5) Cookie/ローカル ストレージ: セッションとログイン状態 (例: トークン、PHPSESSID) に使用されます。ブラウザで削除または制限できます。(6) お客様の権利: 法律で認められている範囲で、アクセス、訂正、削除、同意の撤回などの権利を行使できます。(7) 変更と通知: 更新については目立つように通知します。引き続きご利用いただく場合は、更新された利用規約を読み、同意されたものとみなします。同意いただけない場合は、サービスのご利用を中止し、弊社までご連絡ください。",
